#!/usr/bin/env bash
# Confluence - mainnet bridge offers only chains with Circle Forwarding as destination.
# Changes: confluence-api/src/chains/registry.ts (testnet unchanged).
# Usage: bash stage-mainnet-forwarding-only.sh [--dry-run | --revert]
set -euo pipefail

REPO="${CONFLUENCE_REPO:-$HOME/confluence}"
FILE="confluence-api/src/chains/registry.ts"
MARKER="confluence:mainnet-forwarding-only"
OLD_SHA="a23b345b96f725291260f4f55990f7992b36af57a2b7d695d85f076810099b21"
NEW_SHA="6932d75121429a7426695390b44b35702b567c1af3e2ed1c61fc189381b125f2"
BACKUP_DIR="$REPO/.confluence/backups"
MODE="${1:-apply}"

cd "$REPO" || { echo "repo not found at $REPO"; exit 1; }
[ -f "$FILE" ] || { echo "missing $FILE"; exit 1; }
sha() { sha256sum "$1" | cut -d' ' -f1; }

if [ "$MODE" = "--revert" ]; then
  LAST=$(ls -1t "$BACKUP_DIR"/registry.ts.*.bak 2>/dev/null | head -1 || true)
  [ -n "$LAST" ] || { echo "no backup found in $BACKUP_DIR"; exit 1; }
  [ "$(sha "$LAST")" = "$OLD_SHA" ] || { echo "backup $LAST is not the expected original; not reverting"; exit 1; }
  cp "$LAST" "$FILE"
  echo "reverted $FILE from $LAST"
  exit 0
fi

CUR=$(sha "$FILE")
if [ "$CUR" = "$NEW_SHA" ] || grep -q "$MARKER" "$FILE"; then
  echo "already applied (marker present); nothing to do"; exit 0
fi
[ "$CUR" = "$OLD_SHA" ] || { echo "$FILE is not in the expected prior state (sha $CUR); not touching it"; exit 1; }

TMP=$(mktemp)
trap 'rm -f "$TMP"' EXIT
base64 -d > "$TMP" <<'B64'

B64
[ "$(sha "$TMP")" = "$NEW_SHA" ] || { echo "decoded file failed sha256 check; aborting"; exit 1; }

if [ "$MODE" = "--dry-run" ]; then
  echo "dry run: prior state OK, payload OK. Changes that would be applied:"
  diff -u "$FILE" "$TMP" || true
  exit 0
fi

mkdir -p "$BACKUP_DIR"
STAMP=$(date +%Y%m%d-%H%M%S)
cp "$FILE" "$BACKUP_DIR/registry.ts.$STAMP.bak"
cp "$TMP" "$FILE"
echo "applied. backup: $BACKUP_DIR/registry.ts.$STAMP.bak"
echo "next: cd confluence-api && npm run typecheck"
